mapper.select:
SELECT course_id
FROM enrollment
WHERE id = #{enrollmentId, jdbcType=NUMERIC}

SELECT student_id
FROM enrollment
WHERE id = #{enrollmentId, jdbcType=NUMERIC}

SELECT subject_id
FROM course
WHERE id = #{courseId, jdbcType=NUMERIC}

SELECT COUNT(*)
FROM grade g
         JOIN enrollment e ON g.enrollment_id = e.id
         JOIN course c     ON e.course_id     = c.id
WHERE g.id = #{gradeId}
  AND c.professor_id = #{professorId}

SELECT COUNT(*) 
FROM grade g
JOIN enrollment e ON g.enrollment_id = e.id
WHERE e.course_id = (
    SELECT course_id 
    FROM enrollment 
    WHERE id = #{enrollmentId, jdbcType=NUMERIC}
)
AND g.total_int >= #{score}

SELECT * FROM ( SELECT courseId, courseName, subjectId, subjectName, credit, semesterId, semesterName, semesterYear, enrollmentCount, ROW_NUMBER() OVER (ORDER BY courseId DESC) as rn FROM ( SELECT c.id as courseId, s.name as courseName, s.id as subjectId, s.name as subjectName, s.credit, se.id as semesterId, se.name as semesterName, se.name as semesterYear, COUNT(e.id) as enrollmentCount FROM course c JOIN subject s ON c.subject_id = s.id JOIN semester se ON c.semester_id = se.id LEFT JOIN enrollment e ON c.id = e.course_id WHERE c.professor_id = #{professorId}
AND s.name LIKE '%' || #{searchKeyword} || '%'
AND s.name LIKE '%' || #{searchKeyword} || '%'
GROUP BY c.id, s.id, s.name, s.credit, se.id, se.name ) ) WHERE rn BETWEEN #{start} AND #{end}

SELECT COUNT(DISTINCT c.id) FROM course c JOIN subject s ON c.subject_id = s.id WHERE c.professor_id = #{professorId}
AND s.name LIKE '%' || #{searchKeyword} || '%'
AND s.name LIKE '%' || #{searchKeyword} || '%'

SELECT "subjectId", "subjectName", "credit", "rn" FROM ( SELECT s.id as "subjectId", s.name as "subjectName", s.credit as "credit", ROW_NUMBER() OVER (ORDER BY s.id DESC) as "rn" FROM subject s
AND UPPER(s.name) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND s.id = TO_NUMBER(#{searchKeyword})
AND (UPPER(s.name) LIKE '%' || UPPER(#{searchKeyword}) || '%' OR (REGEXP_LIKE(#{searchKeyword}, '^[0-9]+$') AND s.id = TO_NUMBER(#{searchKeyword})))
) WHERE "rn" BETWEEN #{start} AND #{end}

SELECT * FROM ( SELECT e.id as "enrollmentId", s.id as "subjectId", s.name as "subjectName", s.credit as "credit", g.id as "gradeId", g.alphabet as "alphabet", g.total_int as "totalScore", g.score as "score", g.gpa as "gpa", CASE WHEN g.id IS NULL THEN '미입력' ELSE '입력완료' END as "gradeStatus", ROW_NUMBER() OVER (ORDER BY e.id DESC) as "rn" FROM enrollment e INNER JOIN course c ON e.course_id = c.id INNER JOIN subject s ON c.subject_id = s.id LEFT JOIN grade g ON e.id = g.enrollment_id WHERE e.student_id = #{studentId}
AND UPPER(s.name) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND s.id = TO_NUMBER(#{searchKeyword})
AND EXISTS ( SELECT 1 FROM grade g2 WHERE g2.enrollment_id = e.id AND UPPER(g2.alphabet) LIKE '%' || UPPER(#{searchKeyword}) || '%' )
AND (UPPER(s.name) LIKE '%' || UPPER(#{searchKeyword}) || '%' OR (REGEXP_LIKE(#{searchKeyword}, '^[0-9]+$') AND s.id = TO_NUMBER(#{searchKeyword})) OR EXISTS ( SELECT 1 FROM grade g2 WHERE g2.enrollment_id = e.id AND UPPER(g2.alphabet) LIKE '%' || UPPER(#{searchKeyword}) || '%' ))
) WHERE "rn" BETWEEN #{start} AND #{end}
